# Generated by build.py from recipe.yml for recipe ftp-download-every-file-in-a-folder. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/pub', 'site/pub/archive' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/pub/a.txt'), "alpha`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/pub/b.txt'), "bravo`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/pub/c.txt'), "charlie`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/pub/.hidden'), "not served`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/pub/archive/old.txt'), "from last year`n")
[IO.File]::WriteAllText((Join-Path $PWD 'fetch-folder.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# fetch-folder.sh URL DIR: downloads every file of the FTP folder URL (ending in /) into DIR, in one`n# curl command, and skips the subfolders. Names with spaces are not handled.`nurl=`$1; dir=`$2`nmkdir -p `"`$dir`"`n# The long listing tells folders from files: a folder's line starts with d.`nfolders=`" `$(curl -sS `"`$url`" | tr -d '\r' | awk '/^d/ { print `$NF }' | tr '\n' ' ')`"`nset --`nfor name in `$(curl -sS -l `"`$url`" | tr -d '\r'); do`n  case `"`$folders`" in`n    *`" `$name `"*) echo `"skip `$name/`" ;;`n    *) set -- `"`$@`" -o `"`$dir/`$name`" `"`$url`$name`" ;;`n  esac`ndone`ncurl -sS --fail-early -w `"get %{url.path} %{exitcode}\n`" `"`$@`"`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--list-directories', '--directory', 'site', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh fetch-folder.sh ftp://127.0.0.1:8080/pub/ out } finally { Stop-Process $server0 }
